  v_actor uuid := (select id from profiles where role = 'admin' order by created_at limit 1); v_src mock_exam_sets%rowtype; v_new uuid := gen_random_uuid(); v_cols text; v_cols_i text; sl jsonb; v_npid uuid; v_p problems%rowtype; v_it mock_exam_set_items%rowtype;
  v_slots int := 0; v_slotsj jsonb := '[]'::jsonb; v_bad text; v_hard_before int; v_hard_after int;
begin
  begin
    select * into v_src from mock_exam_sets where name = v_sp->>'name' and status = 'published' and archived_at is null for update;
    if v_src.id is null then raise exception 'published % not found', v_sp->>'name'; end if;
    for sl in select * from jsonb_array_elements(v_sp->'slots') loop
      select * into v_it from mock_exam_set_items i where i.exam_set_id = v_src.id and i.problem_id = (sl->>'oldProblemId')::uuid and i.module_key::text = sl->>'moduleKey' and coalesce(i.route::text, '') = coalesce(sl->>'route', '');
      if v_it.id is not null then v_slotsj := v_slotsj || jsonb_build_array(sl || jsonb_build_object('curSection', v_it.section, 'curPosition', v_it.position)); v_slots := v_slots + 1; end if;
    end loop;
    if v_slots = 0 then raise notice '% nothing to change (already up to date) - skipped', v_src.name; return; end if;
    if exists (select 1 from mock_exam_sets where set_group_id = v_src.set_group_id and status = 'draft' and archived_at is null) then raise notice '% a draft version already exists - skipped (publish/discard it, then re-run)', v_src.name; return; end if;
    perform pg_advisory_xact_lock(hashtextextended('mock_exam_new_version:' || v_src.set_group_id::text, 0));
    select string_agg(quote_ident(column_name), ', ' order by ordinal_position) into v_cols from information_schema.columns where table_schema = 'public' and table_name = 'mock_exam_sets' and is_generated = 'NEVER' and column_name not in ('id', 'version_no', 'status', 'created_by', 'created_at', 'published_at', 'published_by', 'archived_at', 'access_tier', 'readiness_status', 'readiness_report', 'readiness_checked_at');
    execute format('insert into mock_exam_sets (id, version_no, status, created_by, access_tier, %s) select $1, $2, ''draft'', $3, ''tutoring'', %s from mock_exam_sets where id = $4', v_cols, v_cols)
      using v_new, (select max(version_no) + 1 from mock_exam_sets where set_group_id = v_src.set_group_id), v_actor, v_src.id;
    select string_agg(quote_ident(column_name), ', ' order by ordinal_position), string_agg('i.' || quote_ident(column_name), ', ' order by ordinal_position)
      into v_cols, v_cols_i from information_schema.columns where table_schema = 'public' and table_name = 'mock_exam_set_items' and is_generated = 'NEVER' and column_name not in ('id', 'exam_set_id', 'created_at');
    execute format('insert into mock_exam_set_items (exam_set_id, %s) select $1, %s from mock_exam_set_items i where i.exam_set_id = $2
                    and not exists (select 1 from jsonb_to_recordset($3) as x("curSection" text, "curPosition" int) where x."curSection" = i.section and x."curPosition" = i.position)', v_cols, v_cols_i) using v_new, v_src.id, v_slotsj;
    for sl in select * from jsonb_array_elements(v_slotsj) loop
      v_npid := coalesce((sl->>'newProblemId')::uuid, (select problem_id from problem_versions where quality->'mockExamGeneration'->>'gid' = sl->>'newGid' limit 1));
      select * into v_p from problems where id = v_npid;
      if v_p.id is null or v_p.status <> 'confirmed' or v_p.archived_at is not null or v_p.published_version_id is null then raise exception 'replacement for slot %/% not usable (%)', sl->>'curSection', sl->>'curPosition', coalesce(sl->>'newGid', sl->>'newProblemId'); end if;
      if v_p.skill_code is distinct from sl->>'skill' or v_p.difficulty::text <> sl->>'to' or v_p.format::text <> sl->>'format' then raise exception 'replacement % does not match slot (skill/difficulty/format)', v_npid; end if;
      if exists (select 1 from mock_exam_set_items x where x.problem_id = v_npid and x.exam_set_id in (select id from mock_exam_sets where archived_at is null and status <> 'archived' and id <> v_new)) then raise exception 'replacement % already used in another live set', v_npid; end if;
      insert into mock_exam_set_items (exam_set_id, section, position, problem_id, problem_version_id, sat_domain, skill_code, difficulty, module_key, route)
      select v_new, i.section, i.position, v_npid, v_p.published_version_id, v_p.sat_domain, v_p.skill_code, v_p.difficulty, i.module_key, i.route from mock_exam_set_items i where i.exam_set_id = v_src.id and i.section = sl->>'curSection' and i.position = (sl->>'curPosition')::int;
    end loop;
    select count(*) filter (where difficulty = 'hard') into v_hard_before from mock_exam_set_items where exam_set_id = v_src.id and section = 'rw' and (module_key = 'rw_m1' or route = 'lower');
    select count(*) filter (where difficulty = 'hard') into v_hard_after from mock_exam_set_items where exam_set_id = v_new and section = 'rw' and (module_key = 'rw_m1' or route = 'lower');
    if not coalesce((public.mock_exam_validate_mst_set(v_new)->>'ready')::boolean, false) then raise exception 'rw hard set: 4-module/rule validation failed %', public.mock_exam_validate_mst_set(v_new)::text; end if;
    select string_agg(x.problem_id::text || ':' || x.issue, ', ') into v_bad from (select * from public.mock_exam_set_item_issues(v_new) where issue is not null limit 5) x;
    if v_bad is not null then raise exception 'rw hard set: item issues %', v_bad; end if;
    update mock_exam_sets set readiness_status = 'ready', readiness_report = public.mock_exam_validate_mst_set(v_new) || jsonb_build_object('shortfalls', '[]'::jsonb, 'checkedAt', now()), readiness_checked_at = now() where id = v_new;
    update mock_exam_sets set readiness_report = readiness_report || jsonb_build_object('rwHard1022', true) where id = v_new;
    raise notice '% new draft version created (% replaced slots, rw hard in M1/M2-lower % -> %) -> %', v_src.name, v_slots, v_hard_before, v_hard_after, v_new;
  exception when others then raise notice '% SKIPPED: %', v_sp->>'name', sqlerrm;
  end;
end
